package com.catcore.ctrlmietze.multitask.xposed;
import android.app.*; import android.content.*; import android.graphics.*; import android.graphics.drawable.*; import android.view.*; import android.widget.*; import de.robv.android.xposed.*; import de.robv.android.xposed.callbacks.XC_LoadPackage;
public final class MultiTaskHook implements IXposedHookLoadPackage {private static final String SELF="com.catcore.ctrlmietze.multitask"; public void handleLoadPackage(XC_LoadPackage.LoadPackageParam l){if(SELF.equals(l.packageName)){XposedHelpers.findAndHookMethod(SELF+".MainActivity",l.classLoader,"isXposedActive",XC_MethodReplacement.returnConstant(true));return;}XposedHelpers.findAndHookMethod(Activity.class,"onPostResume",new XC_MethodHook(){protected void afterHookedMethod(MethodHookParam p){try{inject((Activity)p.thisObject);}catch(Throwable t){XposedBridge.log("CatCore MultiTask: "+t);}}});}
 private static void inject(Activity a){View v=a.findViewById(android.R.id.content);if(!(v instanceof ViewGroup))return;ViewGroup g=(ViewGroup)v;if(g.findViewWithTag("MTL_BUTTON")!=null)return;TextView b=new TextView(a);b.setTag("MTL_BUTTON");b.setText("Ⅱ");b.setTextColor(Color.WHITE);b.setGravity(Gravity.CENTER);b.setTextSize(18);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.argb(235,70,98,210));bg.setCornerRadius(dp(a,16));b.setBackground(bg);ViewGroup.LayoutParams lp;if(g instanceof FrameLayout){FrameLayout.LayoutParams f=new FrameLayout.LayoutParams(dp(a,48),dp(a,48));f.gravity=Gravity.TOP|Gravity.END;f.topMargin=dp(a,14);f.rightMargin=dp(a,14);lp=f;}else lp=new ViewGroup.LayoutParams(dp(a,48),dp(a,48));g.addView(b,lp);b.setOnClickListener(x->{Intent li=a.getPackageManager().getLaunchIntentForPackage(a.getPackageName());if(li==null||li.getComponent()==null)return;Intent pr=new Intent();pr.setClassName(SELF,SELF+".LaunchProxyActivity");pr.putExtra("target_package",li.getComponent().getPackageName());pr.putExtra("target_activity",li.getComponent().getClassName());pr.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);a.startActivity(pr);});}
 private static int dp(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);} }
